userId = #{item.userId}, goodsId = #{item.goodsId}, addressId = #{item.addressId}, preId = #{item.preId}, goodsName = #{item.goodsName}, `describe` = #{item.describe}, goodsPrice = #{item.goodsPrice}, goodsStock = #{item.goodsStock}, imagePath = #{item.imagePath}, launch = #{item.launch}, createTime = #{item.createTime}, `delete` = #{item.delete},
